"""Listening Batch 2: Material für einen zweiten vollständigen Listening-Test."""
from contentlib import MC, append
mc = MC(start=3, seed=33)

C = []
def ch(id, level, voice, prompt, correct, wrong, why):
    m = mc("", correct, wrong, why); C.append({"id": id, "level": level, "voice": voice, "prompt": prompt, "options": m["options"], "answer": m["answer"], "why": why})
